def allpossibilities(self):
        """Returns all possible outputtemplates that may occur (recusrively applied)"""
        if self.outputtemplate is None:
            return []
        else:
            return [self.outputtemplate] + [
                x.allpossibilities() for x in self.outputtemplates
            ]

